/*
# Seed Batch A: 4 draft surveys from surveys_spec.json

Inserts 4 surveys as drafts (status='draft') into guidance_surveys, linked to
indicators/programs/resources from the Zad reference tables. Idempotent via
ON CONFLICT (slug) DO NOTHING.

Surveys:
1. motivation — مقياس دافعية التعلم (16 items, 4 sections)
2. learning_styles — أنماط المتعلمين (20 items, 4 sections)
3. psychosocial_skills — المهارات النفسية والاجتماعية (14 items, 5 sections)
4. positive_behavior_impact — أثر برنامج تعزيز السلوك الإيجابي (12 items, 4 sections)

No schema changes. No RLS changes. Data-only migration.
*/

INSERT INTO guidance_surveys (slug, title, audience, status, scale, intro, demographics, sections, extra, settings, indicators, programs, resources, publish_gate) VALUES ('motivation', 'مقياس دافعية التعلم', 'student', 'draft', '{"type":"likert5","labels":["لا أوافق بشدة","لا أوافق","محايد","أوافق","أوافق بشدة"]}'::jsonb, 'يهدف هذا المقياس إلى فهم ما يدفعك للتعلم لنساعدك أكثر. لا توجد إجابة صحيحة أو خاطئة، وإجابتك سرية ولا تُسجَّل باسمك.', '[{"id":"grade","text":"الصف","type":"single","options":["الأول الثانوي","الثاني الثانوي","الثالث الثانوي"]}]'::jsonb, '[{"id":"intrinsic","name":"الدافعية الداخلية والاستمتاع","swot_axis":"internal","items":[{"text":"أستمتع بتعلم أشياء جديدة حتى لو لم تدخل في الاختبار.","reverse":false},{"text":"أشعر بالفضول لأعرف أسباب الأشياء التي أدرسها.","reverse":false},{"text":"أجد صعوبة في الاهتمام بالدرس ما لم يكن مرتبطًا بالدرجات فقط.","reverse":true},{"text":"أتحمّس للحصص التي يتيح لي معلمها المشاركة والتجربة.","reverse":false}],"if_low":["تفعيل أنشطة تعلم تطبيقية وتحديات قصيرة بالتنسيق مع المعلمين","تنفيذ برنامج تنمية الدافعية (دليل البرنامج)"]},{"id":"efficacy","name":"الكفاءة الذاتية الأكاديمية","swot_axis":"internal","items":[{"text":"أثق بقدرتي على فهم دروسي إذا بذلت جهدًا.","reverse":false},{"text":"أشعر أن مهما حاولت لن يتحسن مستواي.","reverse":true},{"text":"أستطيع حل المسائل الصعبة بتجزئتها إلى خطوات.","reverse":false},{"text":"عندما أخطئ أعتبر الخطأ فرصة للتعلم.","reverse":false}],"if_low":["جلسات إرشادية جماعية عن عقلية النمو","تعزيز الإنجازات الصغيرة وملف الإنجاز"]},{"id":"value","name":"قيمة التعلم والأهداف","swot_axis":"internal","items":[{"text":"أعرف لماذا أدرس كل مادة وكيف تفيدني مستقبلًا.","reverse":false},{"text":"لدي هدف دراسي أو مهني واضح أعمل من أجله.","reverse":false},{"text":"أرى أن ما أتعلمه لا علاقة له بحياتي.","reverse":true},{"text":"أربط بين دراستي وطموحاتي بعد الثانوية.","reverse":false}],"if_low":["برنامج التوجيه المهني وربطه بالدافعية","لقاء تعريفي بالمسارات والتخصصات"]},{"id":"persistence","name":"المثابرة والتنظيم الذاتي","swot_axis":"internal","items":[{"text":"أكمل مهامي الدراسية حتى عندما أشعر بالملل.","reverse":false},{"text":"أخطط لوقت مذاكرتي قبل الاختبارات بوقت كافٍ.","reverse":false},{"text":"أؤجل واجباتي إلى آخر لحظة.","reverse":true},{"text":"أطلب المساعدة عندما أتعثر في فهم موضوع.","reverse":false}],"if_low":["برنامج تعزيز مهارات النجاح (إدارة الوقت والاستذكار)","متابعة فردية للمؤجِّلين"]}]'::jsonb, '[]'::jsonb, '{"anonymous":true,"one_response_per_device":true}'::jsonb, ARRAY['2-1-1-9','3-2-1-2']::text[], ARRAY['motivation']::text[], ARRAY['p_motivation']::text[], NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO guidance_surveys (slug, title, audience, status, scale, intro, demographics, sections, extra, settings, indicators, programs, resources, publish_gate) VALUES ('learning_styles', 'أنماط المتعلمين (تفضيلات التعلم)', 'student', 'draft', '{"type":"likert5","labels":["لا ينطبق عليّ إطلاقًا","ينطبق قليلًا","ينطبق أحيانًا","ينطبق غالبًا","ينطبق تمامًا"]}'::jsonb, 'لكل واحد منا طريقة يفضلها في التعلم. اختر مدى انطباق كل عبارة عليك. النتيجة تصف تفضيلاتك ولا تُصنّف قدراتك.', '[{"id":"grade","text":"الصف","type":"single","options":["الأول الثانوي","الثاني الثانوي","الثالث الثانوي"]}]'::jsonb, '[{"id":"visual","name":"بصري","swot_axis":"internal","items":[{"text":"أفهم أكثر عندما أرى رسومًا أو خرائط ذهنية أو ألوانًا.","reverse":false},{"text":"أستعيد المعلومة بتخيّل شكلها في الصفحة أو السبورة.","reverse":false},{"text":"أفضل أن ألخّص بالرسم والأسهم والجداول.","reverse":false},{"text":"تشدني الفيديوهات والصور التوضيحية أكثر من النص.","reverse":false},{"text":"أنظّم ملاحظاتي بألوان مختلفة.","reverse":false}],"if_low":[]},{"id":"auditory","name":"سمعي","swot_axis":"internal","items":[{"text":"أفهم أكثر عندما أستمع لشرح المعلم أو زميل.","reverse":false},{"text":"أحب مناقشة الدرس بصوت عالٍ مع زملائي.","reverse":false},{"text":"أراجع بقراءة المعلومات بصوت مسموع أو تسجيلها.","reverse":false},{"text":"أتذكر ما سمعته في الحصة أكثر مما قرأته.","reverse":false},{"text":"تفيدني الشروحات الصوتية والبودكاست التعليمي.","reverse":false}],"if_low":[]},{"id":"readwrite","name":"قرائي/كتابي","swot_axis":"internal","items":[{"text":"أفضل قراءة الكتاب وكتابة الملخصات.","reverse":false},{"text":"أتعلم جيدًا عندما أكتب الأفكار بأسلوبي.","reverse":false},{"text":"أحب قوائم النقاط والتعريفات المكتوبة.","reverse":false},{"text":"أستعيد المعلومة بتذكّر ما كتبته في دفتري.","reverse":false},{"text":"أفضل الإجابة كتابيًا على الشفهي.","reverse":false}],"if_low":[]},{"id":"kinesthetic","name":"حركي/عملي","swot_axis":"internal","items":[{"text":"أفهم أكثر عندما أجرّب بيدي أو أطبّق عمليًا.","reverse":false},{"text":"أشعر بالملل إذا جلست طويلًا دون نشاط.","reverse":false},{"text":"أحب النماذج والمعامل والمشاريع العملية.","reverse":false},{"text":"أتذكر ما فعلته أكثر مما سمعته أو قرأته.","reverse":false},{"text":"أذاكر بالمشي أو الحركة أو استخدام أدوات.","reverse":false}],"if_low":[]}]'::jsonb, '[]'::jsonb, '{"anonymous":true,"one_response_per_device":true}'::jsonb, ARRAY['2-1-1-9']::text[], ARRAY['motivation','success']::text[], ARRAY['p_success','p_motivation']::text[], NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO guidance_surveys (slug, title, audience, status, scale, intro, demographics, sections, extra, settings, indicators, programs, resources, publish_gate) VALUES ('psychosocial_skills', 'مقياس المهارات النفسية والاجتماعية', 'student', 'draft', '{"type":"likert5","labels":["أبدًا","نادرًا","أحيانًا","غالبًا","دائمًا"]}'::jsonb, 'يساعدنا هذا المقياس في فهم المهارات التي نعززها. إنه ليس تشخيصًا ولا حكمًا عليك. اختر ما يصفك غالبًا. إذا شعرت بضيق شديد أخبر الموجه أو شخصًا تثق به.', '[{"id":"grade","text":"الصف","type":"single","options":["الأول الثانوي","الثاني الثانوي","الثالث الثانوي"]}]'::jsonb, '[{"id":"emotion","name":"تنظيم الانفعالات","swot_axis":"internal","items":[{"text":"أهدأ عندما أغضب قبل أن أتصرف.","reverse":false},{"text":"أستطيع تسمية مشاعري وفهم سببها.","reverse":false},{"text":"ينفعل غضبي بسرعة ويصعب علي التحكم فيه.","reverse":true}],"if_low":["جلسات جماعية على تنظيم الانفعالات (تقنيات الاسترخاء والتنفس)"]},{"id":"empathy","name":"التعاطف والعلاقات","swot_axis":"internal","items":[{"text":"أنتبه لمشاعر زملائي وأتفهمها.","reverse":false},{"text":"أحافظ على صداقات صحية ومتبادلة.","reverse":false},{"text":"أشعر بالوحدة بين زملائي في المدرسة.","reverse":true}],"if_low":["برنامج الأقران والأنشطة الجماعية","متابعة الحالات المعزولة اجتماعيًا"]},{"id":"problem","name":"حل المشكلات واتخاذ القرار","swot_axis":"internal","items":[{"text":"أفكر في بدائل قبل اتخاذ قرار مهم.","reverse":false},{"text":"أواجه المشكلات بدل الهروب منها.","reverse":false},{"text":"أستشير من أثق به عند اتخاذ قراراتي.","reverse":false}],"if_low":["ورش مهارات حل المشكلات واتخاذ القرار"]},{"id":"communication","name":"التواصل والحزم","swot_axis":"internal","items":[{"text":"أستطيع التعبير عن رأيي باحترام.","reverse":false},{"text":"أستطيع قول «لا» لما لا يناسبني بلباقة.","reverse":false},{"text":"أستمع لرأي غيري دون مقاطعة.","reverse":false}],"if_low":["تدريب على مهارات الحوار والحزم (مشاهد تمثيلية)"]},{"id":"resilience","name":"المرونة والتعامل مع الضغوط","swot_axis":"internal","items":[{"text":"أتعافى بسرعة بعد المواقف الصعبة.","reverse":false},{"text":"لدي طرق صحية للتعامل مع التوتر (رياضة، حديث مع أحد…).","reverse":false},{"text":"أستسلم عندما تتراكم علي الضغوط.","reverse":true}],"if_low":["برنامج الوقاية النفسية وبناء المرونة","التنسيق مع الموجه الصحي عند الحاجة"]}]'::jsonb, '[{"id":"want_talk","text":"أرغب في مقابلة الموجه الطلابي (اختياري)","type":"optin_contact","note":"يظهر الاسم/الفصل للموجه فقط عند اختيار الطالب"}]'::jsonb, '{"anonymous":true,"one_response_per_device":true}'::jsonb, ARRAY['1-2-1-4','1-3-1-1','1-5-1-1','1-5-1-2','2-1-1-8','3-2-1-2']::text[], ARRAY['psychosocial','prevention']::text[], ARRAY['g_psych','p_success']::text[], NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO guidance_surveys (slug, title, audience, status, scale, intro, demographics, sections, extra, settings, indicators, programs, resources, publish_gate) VALUES ('positive_behavior_impact', 'أثر برنامج تعزيز السلوك الإيجابي', 'student', 'draft', '{"type":"likert5","labels":["لا أوافق بشدة","لا أوافق","محايد","أوافق","أوافق بشدة"]}'::jsonb, 'نريد أن نعرف أثر برنامج تعزيز السلوك الإيجابي عليك وعلى بيئة المدرسة.', '[{"id":"grade","text":"الصف","type":"single","options":["الأول الثانوي","الثاني الثانوي","الثالث الثانوي"]}]'::jsonb, '[{"id":"awareness","name":"وضوح السلوك المتوقع","swot_axis":"internal","items":[{"text":"أعرف السلوكيات المتوقعة مني في المدرسة بوضوح.","reverse":false},{"text":"أعرف ماذا يترتب على الالتزام وعلى المخالفة.","reverse":false},{"text":"أعرف أمثلة للسلوك المتميز الذي يُكرَّم عليه الطلاب.","reverse":false}],"if_low":["إعادة التعريف بقواعد السلوك والمواظبة في طابور وحصص التوجيه الجمعي"]},{"id":"recognition","name":"التقدير والتعزيز","swot_axis":"internal","items":[{"text":"أشعر أن المدرسة تلاحظ سلوكي الجيد وتقدّره.","reverse":false},{"text":"أجد أن التكريم يتم بعدالة ووفق معايير واضحة.","reverse":false},{"text":"التعزيز الإيجابي يحفزني على الاستمرار.","reverse":false}],"if_low":["مراجعة آلية التعزيز والتكريم (إطار الاحتفاء والتكريم)"]},{"id":"behavior","name":"الالتزام الفعلي","swot_axis":"internal","items":[{"text":"ألتزم بالحضور في وقت الطابور والحصص.","reverse":false},{"text":"أتعامل باحترام مع زملائي ومعلميّ.","reverse":false},{"text":"أحافظ على ممتلكات المدرسة وأرتب مكاني.","reverse":false}],"if_low":["متابعة فردية للمتكررين وربطهم بجلسات إرشادية"]},{"id":"climate","name":"المناخ والعلاقات","swot_axis":"external","items":[{"text":"لاحظت تحسنًا في الهدوء والاحترام داخل الفصل.","reverse":false},{"text":"لاحظت انخفاضًا في الشجار والمشكلات بين الطلاب.","reverse":false},{"text":"أشعر بانتماء أكبر للمدرسة هذا الفصل.","reverse":false}],"if_low":["تعزيز دور المجلس الطلابي في المبادرات السلوكية"]}]'::jsonb, '[{"id":"open1","text":"ما أكثر نشاط أو تكريم أثّر فيك إيجابيًا؟","type":"text"},{"id":"open2","text":"ما اقتراحك لتحسين البرنامج؟","type":"text"}]'::jsonb, '{"anonymous":true,"one_response_per_device":true}'::jsonb, ARRAY['1-2-1-1','1-2-1-3','1-2-1-4','1-3-1-1','3-2-1-1','3-2-1-2','3-2-1-5','3-2-1-7']::text[], ARRAY['positive']::text[], ARRAY['p_positive','g_conduct']::text[], NULL) ON CONFLICT (slug) DO NOTHING;